import XCTest
import UIKit

final class DumpTests: XCTestCase {
    func testDump() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        sleep(2)
        let titles = app.staticTexts.matching(identifier: "TitleLabel").matching(NSPredicate(format: "label == %@", "Team Standup")).allElementsBoundByIndex
        let visible = titles.first { $0.frame.minY > 300 && $0.frame.minY < 800 }
        visible?.tap()
        sleep(3)
        let msg = app.descendants(matching: .any).matching(NSPredicate(format: "label CONTAINS %@", "Morning all")).firstMatch
        msg.press(forDuration: 1.5)
        sleep(2)
        let thumb = app.buttons.matching(NSPredicate(format: "label == %@", "👍")).firstMatch
        XCTAssertTrue(thumb.waitForExistence(timeout: 5))
        thumb.tap()
        sleep(3)
        try XCUIScreen.main.screenshot().image.pngData()?.write(to: URL(fileURLWithPath: "/private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/after.png"))
        try app.debugDescription.write(toFile: "/private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/after.txt", atomically: true, encoding: .utf8)
    }
}

